"use client";
import * as React from "react";
import { cn } from "../lib/cn";
import { Slot, slotChildren } from "../lib/slot";
import { useControllableState, useOutsideClick } from "../lib/hooks";
import { Icon } from "../icons/icon";

export interface FabProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  icon?: React.ReactNode;
  /** Tekst naast het icoon; zonder tekst blijft het een ronde knop. */
  children?: React.ReactNode;
  size?: "md" | "lg";
  /** Vaste plek rechtsonder (standaard) of gewoon in de stroom. */
  position?: "bottom-right" | "bottom-left" | "static";
  asChild?: boolean;
}

/** Fab — zwevende hoofdactie, meestal rechtsonder op mobiel. */
export const Fab = React.forwardRef<HTMLButtonElement, FabProps>(function Fab(
  { icon, children, size = "md", position = "bottom-right", asChild, className, ...rest },
  ref
) {
  const Comp = (asChild ? Slot : "button") as React.ElementType;
  const slot = slotChildren(asChild, children);

  return (
    <Comp
      ref={ref}
      type={asChild ? undefined : "button"}
      className={cn(
        "lui-fab",
        `lui-fab-${size}`,
        position !== "static" && `lui-fab-${position}`,
        !slot.inner && "lui-fab-rond",
        className
      )}
      {...rest}
    >
      {slot.wrap(
        <>
          {icon ?? <Icon name="plus" size={size === "lg" ? 24 : 20} />}
          {slot.inner && <span className="lui-fab-label">{slot.inner}</span>}
        </>
      )}
    </Comp>
  );
});

/* ------------------------------------------------------------------ */
/* SpeedDial                                                           */
/* ------------------------------------------------------------------ */
export interface SpeedDialProps extends Omit<React.HTMLAttributes<HTMLDivElement>, "onChange"> {
  open?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
  position?: "bottom-right" | "bottom-left" | "static";
  /** Knop die het waaiertje opent. */
  trigger?: React.ReactNode;
  label?: string;
}

/**
 * SpeedDial — Fab die openklapt naar een paar snelle acties.
 * De acties zet je erin als <SpeedDialAction>.
 */
export const SpeedDial = React.forwardRef<HTMLDivElement, SpeedDialProps>(function SpeedDial(
  { open, defaultOpen = false, onOpenChange, position = "bottom-right", trigger, label = "Snelle acties", className, children, ...rest },
  ref
) {
  const [isOpen, setIsOpen] = useControllableState<boolean>({
    value: open,
    defaultValue: defaultOpen,
    onChange: onOpenChange,
  });
  const eigen = React.useRef<HTMLDivElement | null>(null);

  useOutsideClick([eigen], () => setIsOpen(false), isOpen);

  return (
    <div
      ref={(node) => {
        eigen.current = node;
        if (typeof ref === "function") ref(node as HTMLDivElement);
        else if (ref) (ref as React.RefObject<HTMLDivElement | null>).current = node;
      }}
      data-state={isOpen ? "open" : "closed"}
      className={cn("lui-speeddial", position !== "static" && `lui-fab-${position}`, className)}
      onKeyDown={(event) => {
        if (event.key === "Escape") setIsOpen(false);
      }}
      {...rest}
    >
      <div className="lui-speeddial-acties" role="menu" aria-label={label} hidden={!isOpen}>
        {children}
      </div>
      {trigger ?? (
        <Fab
          position="static"
          aria-expanded={isOpen}
          aria-label={label}
          className="lui-speeddial-trigger"
          icon={<Icon name={isOpen ? "x" : "plus"} size={20} />}
          onClick={() => setIsOpen(!isOpen)}
        />
      )}
    </div>
  );
});

export interface SpeedDialActionProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  icon: React.ReactNode;
  /** Tekst links van de knop. */
  label: React.ReactNode;
}

export const SpeedDialAction = React.forwardRef<HTMLButtonElement, SpeedDialActionProps>(
  function SpeedDialAction({ icon, label, className, ...rest }, ref) {
    return (
      <button ref={ref} type="button" role="menuitem" className={cn("lui-speeddial-actie", className)} {...rest}>
        <span className="lui-speeddial-actie-label">{label}</span>
        <span className="lui-speeddial-actie-icoon">{icon}</span>
      </button>
    );
  }
);

/* ============================ Fab & SpeedDial ============================ */
.lui-fab {
  display: inline-flex; align-items: center; gap: 10px;
  height: 56px; padding: 0 20px; border: none; border-radius: var(--r-full);
  background: var(--accent); color: var(--accent-fg);
  font: inherit; font-size: 14.5px; font-weight: 650; cursor: pointer;
  box-shadow: var(--sh-lg);
  transition: transform var(--dur-fast) var(--ease), box-shadow var(--dur-fast) var(--ease),
    background var(--dur-fast) var(--ease);
}
.lui-fab:hover { background: var(--accent-hover, var(--accent)); transform: translateY(-1px); }
.lui-fab:active { transform: translateY(0); }
.lui-fab:focus-visible { outline: none; box-shadow: var(--sh-lg), var(--ring); }
.lui-fab:disabled { opacity: .5; cursor: not-allowed; box-shadow: none; }
.lui-fab svg { width: 20px; height: 20px; }

.lui-fab-rond { width: 56px; padding: 0; justify-content: center; }
.lui-fab-lg { height: 64px; padding: 0 24px; font-size: 15.5px; }
.lui-fab-lg.lui-fab-rond { width: 64px; padding: 0; }
.lui-fab-label { white-space: nowrap; }

.lui-fab-bottom-right,
.lui-fab-bottom-left {
  position: fixed; z-index: var(--z-sticky);
  bottom: calc(22px + env(safe-area-inset-bottom, 0px));
}
.lui-fab-bottom-right { right: 22px; }
.lui-fab-bottom-left { left: 22px; }

/* ---------- SpeedDial ---------- */
.lui-speeddial { display: inline-flex; flex-direction: column; align-items: flex-end; gap: 12px; }
.lui-fab-bottom-left.lui-speeddial { align-items: flex-start; }

.lui-speeddial-acties { display: flex; flex-direction: column; align-items: inherit; gap: 10px; }

.lui-speeddial-actie {
  display: inline-flex; align-items: center; gap: 10px;
  padding: 0; border: none; background: transparent; cursor: pointer; font: inherit;
  animation: lui-speeddial-in var(--dur) var(--ease-out) both;
}
.lui-speeddial-actie-label {
  padding: 5px 10px; border-radius: var(--r-sm);
  background: var(--surface); border: 1px solid var(--border);
  box-shadow: var(--sh-sm); font-size: 12.5px; font-weight: 600; color: var(--text);
  white-space: nowrap;
}
.lui-speeddial-actie-icoon {
  display: grid; place-items: center; width: 44px; height: 44px; flex: none;
  border-radius: var(--r-full); background: var(--surface);
  border: 1px solid var(--border); box-shadow: var(--sh-md); color: var(--text);
  transition: background var(--dur-fast) var(--ease);
}
.lui-speeddial-actie:hover .lui-speeddial-actie-icoon { background: var(--surface-2); }
.lui-speeddial-actie:focus-visible .lui-speeddial-actie-icoon { box-shadow: var(--ring); }
.lui-speeddial-actie svg { width: 18px; height: 18px; }

@keyframes lui-speeddial-in {
  from { opacity: 0; transform: translateY(8px) scale(.96); }
  to { opacity: 1; transform: none; }
}

@media (prefers-reduced-motion: reduce) {
  .lui-speeddial-actie { animation-duration: .01ms; }
}
